class Kopi:
    def __init__(self, nama, harga):
        self.nama = nama
        self.harga = harga

k = Kopi('Latte', 20000)
print(k.nama, k.harga)

class Hewan:
    def bersuara(self):
        print('Meow!')
h = Hewan()
h.bersuara()

class Karakter:
    def __init__(self, nama):
        self.nama = nama
        self.hp = 100
hero = Karakter('Satria')
print(f'{hero.nama} siap bertarung! HP: {hero.hp}')
